import 'dart:io';
import 'package:dart_basics_tepenchak/models/university.dart';
import 'package:dart_basics_tepenchak/utils/data_processor.dart';
void main() { print('=== Dart Collections & Data Processing Demo ==='); demonstrateLists(); demonstrateSets(); demonstrateMaps(); demonstrateAdvancedOperations(); }
void demonstrateLists() { final nums=[5,2,8,3,1]; print('Sorted: ${[...nums]..sort()}'); print('Even: ${DataProcessor.filterEvenNumbers(nums)}'); print('map: ${nums.map((n)=>n*2).toList()}, where: ${nums.where((n)=>n>3).toList()}, fold: ${nums.fold<int>(0,(a,b)=>a+b)}, reduce: ${nums.reduce((a,b)=>a+b)}'); }
void demonstrateSets() { final a={1,2,3}; final b={2,3,4}; print('Union: ${a.union(b)}, intersection: ${a.intersection(b)}'); }
void demonstrateMaps() { print('Words: ${DataProcessor.countWords('Dart Dart Flutter')}'); final scores={'Dart':90,'Flutter':85}; print('Map transformed: ${scores.map((k,v)=>MapEntry(k,v+5))}'); }
void demonstrateAdvancedOperations() { final students=<Student>[]; final lines=File('data/students.csv').readAsLinesSync().skip(1); for(final line in lines) { final parts=line.split(','); if(parts.length<7) continue; final student=Student(id:parts[0],firstName:parts[1],lastName:parts[2],birthDate:DateTime.parse(parts[3]),skills:parts[6].split(';')); student.addGrade(parts[4],double.parse(parts[5])); students.add(student); } final university=University(name:'CSV Demo',students:students); print('By GPA: ${DataProcessor.sortStudentsByGPA(students)}'); print('Unique skills: ${DataProcessor.getUniqueSkills(students)}'); print('Common courses: ${DataProcessor.findCommonCourses(students)}'); print('Groups by birth year: ${DataProcessor.groupStudentsByYear(students).map((k,v)=>MapEntry(k,v.length))}'); print('Course averages: ${DataProcessor.calculateAverageGradesByCourse(students)}'); final report=DataProcessor.generateReport(university); print('Report: $report'); Directory('output').createSync(recursive:true); File('output/analysis_report.txt').writeAsStringSync('University: ${university.name}\nStatistics: ${university.generateStatistics()}\nStudents: $report\n'); final timer=Stopwatch()..start(); for(var i=0;i<1000;i++) { DataProcessor.sortStudentsByGPA(students); } timer.stop(); print('Benchmark: 1000 sorts in ${timer.elapsedMicroseconds} microseconds'); }
